param(
    [string]$UpdateConfirmPath = '',
    [string]$UpdateToken = ''
)

Add-Type -AssemblyName System.Windows.Forms
Add-Type -AssemblyName System.Drawing
[System.Windows.Forms.Application]::EnableVisualStyles()

# BandaNV v1.0 RC1
$script:AppVersion = '1.0 RC1.9'
$script:GitHubRepo = 'nachodavin/BandaNV'
$script:GitHubApiBase = 'https://api.github.com/repos/nachodavin/BandaNV'

# Determina la carpeta real de BandaNV tanto al ejecutar el .ps1 como el .exe compilado con PS2EXE.
$script:AppDir = $null
if ($PSScriptRoot -and (Test-Path -LiteralPath $PSScriptRoot -PathType Container)) {
    $script:AppDir = $PSScriptRoot
}
if ([string]::IsNullOrWhiteSpace($script:AppDir)) {
    try {
        $exePath = [System.Diagnostics.Process]::GetCurrentProcess().MainModule.FileName
        if (-not [string]::IsNullOrWhiteSpace($exePath)) {
            $script:AppDir = [System.IO.Path]::GetDirectoryName($exePath)
        }
    } catch {}
}
if ([string]::IsNullOrWhiteSpace($script:AppDir)) {
    [System.Windows.Forms.MessageBox]::Show('No se pudo determinar la carpeta de BandaNV.', 'BandaNV', 'OK', 'Error') | Out-Null
    exit 1
}
$script:ConfigDir = Join-Path $script:AppDir 'config'
$script:LogsDir = Join-Path $script:AppDir 'logs'
$script:ConfigPath = Join-Path $script:ConfigDir 'bandanv_config.json'
$script:UpdateStatePath = Join-Path $script:ConfigDir 'bandanv_update_state.json'

# ============================================================
# BandaNV RC1.9 - Identidad visual Dark Elegant + Updater Phase 2
# Paleta grafito + teal tomada del branding oficial.
# Los PNG originales del usuario se conservan sin redibujarlos:
# el wordmark se incrusta como bytes PNG y el icono NV provisto
# se usa para el ejecutable y las ventanas.
# ============================================================
$script:ThemeBg = [Drawing.Color]::FromArgb(20,24,28)
$script:ThemeSurface = [Drawing.Color]::FromArgb(28,34,39)
$script:ThemeSurfaceAlt = [Drawing.Color]::FromArgb(34,41,47)
$script:ThemeInput = [Drawing.Color]::FromArgb(16,20,24)
$script:ThemeBorder = [Drawing.Color]::FromArgb(55,65,73)
$script:ThemeText = [Drawing.Color]::FromArgb(242,244,245)
$script:ThemeTextMuted = [Drawing.Color]::FromArgb(156,163,170)
$script:ThemeAccent = [Drawing.Color]::FromArgb(59,210,185)
$script:ThemeAccentHover = [Drawing.Color]::FromArgb(82,221,199)
$script:ThemeAccentPressed = [Drawing.Color]::FromArgb(45,181,160)
$script:ThemeDanger = [Drawing.Color]::FromArgb(232,116,126)
$script:ThemeDangerHover = [Drawing.Color]::FromArgb(72,38,43)

$script:BrandLogoBase64 = @'

'@
$script:BrandIconBase64 = @'

'@

try {
    Add-Type -TypeDefinition @"
using System;
using System.Runtime.InteropServices;
public static class BandaNVDwm {
    [DllImport("dwmapi.dll")]
    public static extern int DwmSetWindowAttribute(IntPtr hwnd, int attr, ref int attrValue, int attrSize);
}
"@ -ErrorAction Stop
} catch {}

function Get-BrandLogoImage {
    try {
        $bytes=[Convert]::FromBase64String($script:BrandLogoBase64)
        $ms=[IO.MemoryStream]::new($bytes)
        $src=[Drawing.Image]::FromStream($ms)
        $bmp=[Drawing.Bitmap]::new([int]$src.Width,[int]$src.Height)
        $g=[Drawing.Graphics]::FromImage($bmp)
        $g.DrawImageUnscaled($src,0,0)
        $g.Dispose(); $src.Dispose(); $ms.Dispose()
        return $bmp
    } catch { return $null }
}

function Get-BrandIcon {
    try {
        $bytes=[Convert]::FromBase64String($script:BrandIconBase64)
        $ms=[IO.MemoryStream]::new($bytes)
        $icon=[Drawing.Icon]::new($ms)
        $clone=$icon.Clone()
        $icon.Dispose(); $ms.Dispose()
        return $clone
    } catch { return $null }
}

function Enable-DarkTitleBar($form) {
    try {
        $value=1
        $result=[BandaNVDwm]::DwmSetWindowAttribute($form.Handle,20,[ref]$value,4)
        if($result -ne 0) { [void][BandaNVDwm]::DwmSetWindowAttribute($form.Handle,19,[ref]$value,4) }
    } catch {}
}

function Set-SecondaryButtonStyle($button) {
    if($null -eq $button){return}
    $button.FlatStyle=[Windows.Forms.FlatStyle]::Flat
    $button.UseVisualStyleBackColor=$false
    $button.BackColor=$script:ThemeSurfaceAlt
    $button.ForeColor=$script:ThemeText
    $button.FlatAppearance.BorderSize=1
    $button.FlatAppearance.BorderColor=$script:ThemeBorder
    $button.FlatAppearance.MouseOverBackColor=[Drawing.Color]::FromArgb(42,51,58)
    $button.FlatAppearance.MouseDownBackColor=[Drawing.Color]::FromArgb(31,38,43)
    $button.Cursor=[Windows.Forms.Cursors]::Hand
}

function Set-PrimaryButtonStyle($button) {
    if($null -eq $button){return}
    $button.FlatStyle=[Windows.Forms.FlatStyle]::Flat
    $button.UseVisualStyleBackColor=$false
    $button.BackColor=$script:ThemeAccent
    $button.ForeColor=[Drawing.Color]::FromArgb(10,25,23)
    $button.FlatAppearance.BorderSize=0
    $button.FlatAppearance.MouseOverBackColor=$script:ThemeAccentHover
    $button.FlatAppearance.MouseDownBackColor=$script:ThemeAccentPressed
    $button.Cursor=[Windows.Forms.Cursors]::Hand
}

function Set-UndoButtonAvailability($button,[bool]$available) {
    if($null -eq $button){return}
    $button.Enabled=$available
    if($available) {
        Set-PrimaryButtonStyle $button
    } else {
        Set-SecondaryButtonStyle $button
        $button.BackColor=$script:ThemeSurfaceAlt
        $button.ForeColor=$script:ThemeTextMuted
        $button.Cursor=[Windows.Forms.Cursors]::Default
    }
}

function Set-DangerButtonStyle($button) {
    if($null -eq $button){return}
    Set-SecondaryButtonStyle $button
    $button.ForeColor=$script:ThemeDanger
    $button.FlatAppearance.BorderColor=[Drawing.Color]::FromArgb(91,52,57)
    $button.FlatAppearance.MouseOverBackColor=$script:ThemeDangerHover
}

function Apply-DarkTheme($control) {
    if($null -eq $control){return}
    if($control -is [Windows.Forms.Form]) {
        $control.BackColor=$script:ThemeBg
        $control.ForeColor=$script:ThemeText
    } elseif($control -is [Windows.Forms.Button]) {
        Set-SecondaryButtonStyle $control
    } elseif($control -is [Windows.Forms.TextBoxBase]) {
        $control.BackColor=$script:ThemeInput
        $control.ForeColor=$script:ThemeText
        $control.BorderStyle=[Windows.Forms.BorderStyle]::FixedSingle
    } elseif($control -is [Windows.Forms.ListView]) {
        $control.BackColor=$script:ThemeInput
        $control.ForeColor=$script:ThemeText
        $control.BorderStyle=[Windows.Forms.BorderStyle]::FixedSingle
    } elseif($control -is [Windows.Forms.GroupBox]) {
        $control.BackColor=$script:ThemeSurface
        $control.ForeColor=$script:ThemeText
    } elseif($control -is [Windows.Forms.RadioButton]) {
        $control.BackColor=$control.Parent.BackColor
        $control.ForeColor=$script:ThemeText
        $control.UseVisualStyleBackColor=$false
    } elseif($control -is [Windows.Forms.CheckBox]) {
        $control.BackColor=$control.Parent.BackColor
        $control.ForeColor=$script:ThemeText
        $control.UseVisualStyleBackColor=$false
    } elseif($control -is [Windows.Forms.Panel]) {
        $control.BackColor=$script:ThemeSurface
        $control.ForeColor=$script:ThemeText
    } elseif($control -is [Windows.Forms.Label]) {
        $control.ForeColor=$script:ThemeText
    }

    foreach($child in @($control.Controls)) { Apply-DarkTheme $child }
}

function Initialize-ThemedForm($form) {
    $form.BackColor=$script:ThemeBg
    $form.ForeColor=$script:ThemeText
    $form.Font=[Drawing.Font]::new('Segoe UI',9)
    $ico=Get-BrandIcon
    if($null -ne $ico){ $form.Icon=$ico }
    Enable-DarkTitleBar $form
}




# ============================================================
# BandaNV Updater - Phase 1
# GitHub Releases es la única fuente de verdad.
# Esta fase detecta versiones y muestra la UI; todavía NO instala.
# ============================================================

$script:UpdateCheckTimer=$null

function Test-BandaNVPrereleaseVersion([string]$version=$script:AppVersion) {
    return -not [string]::IsNullOrWhiteSpace($version) -and ($version -match '(?i)\bRC[0-9]')
}

function ConvertTo-BandaNVVersionInfo([string]$value) {
    if([string]::IsNullOrWhiteSpace($value)){ return $null }
    $raw=$value.Trim()
    if($raw -notmatch '^[vV]?(?<major>\d+)\.(?<minor>\d+)(?:\.(?<patch>\d+))?(?:[-\s]*(?i:rc)(?<rc>\d+(?:\.\d+)*))?$'){
        return $null
    }

    $rcParts=@()
    if(-not [string]::IsNullOrWhiteSpace([string]$Matches['rc'])) {
        $rcParts=@(([string]$Matches['rc']).Split('.') | ForEach-Object { [int]$_ })
    }

    [PSCustomObject]@{
        Raw=$raw
        Major=[int]$Matches['major']
        Minor=[int]$Matches['minor']
        Patch=if([string]::IsNullOrWhiteSpace([string]$Matches['patch'])){0}else{[int]$Matches['patch']}
        IsPrerelease=($rcParts.Count -gt 0)
        RcParts=$rcParts
    }
}

function Compare-BandaNVVersionInfo($a,$b) {
    if($null -eq $a -or $null -eq $b){ throw 'No se puede comparar una versión inválida.' }

    foreach($p in @('Major','Minor','Patch')) {
        $av=[int]$a.$p
        $bv=[int]$b.$p
        if($av -gt $bv){ return 1 }
        if($av -lt $bv){ return -1 }
    }

    if([bool]$a.IsPrerelease -and -not [bool]$b.IsPrerelease){ return -1 }
    if(-not [bool]$a.IsPrerelease -and [bool]$b.IsPrerelease){ return 1 }
    if(-not [bool]$a.IsPrerelease -and -not [bool]$b.IsPrerelease){ return 0 }

    $ap=@($a.RcParts)
    $bp=@($b.RcParts)
    $max=[Math]::Max($ap.Count,$bp.Count)
    for($i=0;$i -lt $max;$i++) {
        $av=if($i -lt $ap.Count){[int]$ap[$i]}else{0}
        $bv=if($i -lt $bp.Count){[int]$bp[$i]}else{0}
        if($av -gt $bv){ return 1 }
        if($av -lt $bv){ return -1 }
    }
    return 0
}

function Format-BandaNVReleaseTag([string]$tag) {
    if([string]::IsNullOrWhiteSpace($tag)){ return '' }
    $display=$tag.Trim()
    if($display -notmatch '^[vV]'){ $display='v'+$display }
    $display=[regex]::Replace($display,'(?i)-rc',' RC')
    return $display
}

function Get-BandaNVReleaseApiUri {
    if(Test-BandaNVPrereleaseVersion) {
        return ($script:GitHubApiBase + '/releases?per_page=30')
    }
    return ($script:GitHubApiBase + '/releases/latest')
}

function Invoke-BandaNVReleaseRequest {
    try {
        [Net.ServicePointManager]::SecurityProtocol = [Net.ServicePointManager]::SecurityProtocol -bor [Net.SecurityProtocolType]::Tls12
    } catch {}

    $headers=@{
        Accept='application/vnd.github+json'
        'X-GitHub-Api-Version'='2022-11-28'
    }

    return Invoke-RestMethod -Uri (Get-BandaNVReleaseApiUri) -Method Get -Headers $headers -UserAgent 'BandaNV-Updater/1.0' -TimeoutSec 8 -ErrorAction Stop
}

function Select-BandaNVTargetRelease($payload) {
    $bestRelease=$null
    $bestVersion=$null

    foreach($release in @($payload)) {
        if($null -eq $release){ continue }
        if([bool]$release.draft){ continue }

        # Una versión estable usa /releases/latest, que ya excluye pre-releases.
        # Una RC consulta /releases y puede ver tanto RCs como una estable más nueva.
        $version=ConvertTo-BandaNVVersionInfo ([string]$release.tag_name)
        if($null -eq $version){ continue }

        if($null -eq $bestVersion -or (Compare-BandaNVVersionInfo $version $bestVersion) -gt 0) {
            $bestVersion=$version
            $bestRelease=$release
        }
    }

    return $bestRelease
}


function Get-BandaNVFailedUpdateTag {
    if(-not (Test-Path -LiteralPath $script:UpdateStatePath -PathType Leaf)){ return '' }
    try {
        $state=Get-Content -LiteralPath $script:UpdateStatePath -Raw -Encoding UTF8 | ConvertFrom-Json
        if($null -eq $state -or $null -eq $state.PSObject.Properties['failedUpdateTag']){ return '' }
        return [string]$state.failedUpdateTag
    } catch {
        return ''
    }
}

function Clear-BandaNVFailedUpdateStateIfObsolete {
    $failedTag=Get-BandaNVFailedUpdateTag
    if([string]::IsNullOrWhiteSpace($failedTag)){ return }

    try {
        $failedVersion=ConvertTo-BandaNVVersionInfo $failedTag
        $currentVersion=ConvertTo-BandaNVVersionInfo $script:AppVersion
        if($null -ne $failedVersion -and $null -ne $currentVersion -and (Compare-BandaNVVersionInfo $currentVersion $failedVersion) -ge 0) {
            Remove-Item -LiteralPath $script:UpdateStatePath -Force -ErrorAction SilentlyContinue
        }
    } catch {}
}

function Get-BandaNVUpdateResultFromPayload($payload) {
    $currentVersion=ConvertTo-BandaNVVersionInfo $script:AppVersion
    if($null -eq $currentVersion) {
        return [PSCustomObject]@{Status='Error';Message='La versión instalada de BandaNV no tiene un formato reconocido.'}
    }

    $release=Select-BandaNVTargetRelease $payload
    if($null -eq $release) {
        return [PSCustomObject]@{Status='Error';Message='GitHub no devolvió ninguna Release compatible de BandaNV.'}
    }

    $availableVersion=ConvertTo-BandaNVVersionInfo ([string]$release.tag_name)
    if($null -eq $availableVersion) {
        return [PSCustomObject]@{Status='Error';Message='La última Release de GitHub tiene un tag que BandaNV no reconoce.'}
    }

    $comparison=Compare-BandaNVVersionInfo $availableVersion $currentVersion
    $status=if($comparison -gt 0){'Available'}elseif($comparison -eq 0){'Current'}else{'LocalNewer'}

    # Si NVupdate hizo rollback de esta misma Release, no la ofrecemos otra vez
    # automáticamente. Una Release posterior sí vuelve a estar disponible.
    $failedTag=Get-BandaNVFailedUpdateTag
    if($status -eq 'Available' -and -not [string]::IsNullOrWhiteSpace($failedTag) -and ([string]$release.tag_name -ieq $failedTag)) {
        $status='FailedSuppressed'
    }

    $assets=@($release.assets)
    # El actualizador automático NUNCA usa Portable.zip como fallback.
    # Solo acepta el paquete oficial *_AutoUpdate.zip de la misma Release.
    $asset=$assets | Where-Object { ([string]$_.name) -match '(?i)_AutoUpdate\.zip$' } | Select-Object -First 1

    [PSCustomObject]@{
        Status=$status
        Installed=('v'+$script:AppVersion)
        Available=(Format-BandaNVReleaseTag ([string]$release.tag_name))
        Tag=[string]$release.tag_name
        ReleaseName=[string]$release.name
        ReleaseUrl=[string]$release.html_url
        IsPrerelease=[bool]$release.prerelease
        AssetName=if($null -ne $asset){[string]$asset.name}else{''}
        AssetUrl=if($null -ne $asset){[string]$asset.browser_download_url}else{''}
        Digest=if($null -ne $asset -and $null -ne $asset.PSObject.Properties['digest']){[string]$asset.digest}else{''}
        Message=''
    }
}

function Invoke-BandaNVUpdateCheck {
    try {
        $payload=Invoke-BandaNVReleaseRequest
        return Get-BandaNVUpdateResultFromPayload $payload
    } catch {
        return [PSCustomObject]@{
            Status='Error'
            Message=('No se pudo consultar GitHub Releases. ' + $_.Exception.Message)
        }
    }
}


function New-BandaNVUpdateWorkspace {
    $token=[Guid]::NewGuid().ToString('N')
    $root=Join-Path ([IO.Path]::GetTempPath()) ('BandaNV\update-'+$token)
    $extract=Join-Path $root 'extracted'
    $backup=Join-Path $root 'backup\BandaNV.exe'
    $confirm=Join-Path $root 'confirmed.json'
    $zip=Join-Path $root 'AutoUpdate.zip'

    New-Item -ItemType Directory -Force -Path $root,$extract,(Split-Path -Parent $backup) | Out-Null

    [PSCustomObject]@{
        Token=$token
        Root=$root
        ZipPath=$zip
        ExtractDir=$extract
        BackupPath=$backup
        ConfirmPath=$confirm
        StagedExe=(Join-Path $extract 'BandaNV.exe')
    }
}

function Remove-BandaNVUpdateWorkspace($workspace) {
    if($null -eq $workspace -or [string]::IsNullOrWhiteSpace([string]$workspace.Root)){ return }
    try {
        $tempBase=[IO.Path]::GetFullPath((Join-Path ([IO.Path]::GetTempPath()) 'BandaNV'))
        $candidate=[IO.Path]::GetFullPath([string]$workspace.Root)
        if($candidate.StartsWith($tempBase,[StringComparison]::OrdinalIgnoreCase) -and (Test-Path -LiteralPath $candidate)) {
            Remove-Item -LiteralPath $candidate -Recurse -Force -ErrorAction SilentlyContinue
        }
    } catch {}
}

function Test-BandaNVUpdateDigest([string]$filePath,[string]$digest) {
    if([string]::IsNullOrWhiteSpace($digest)){ throw 'GitHub no publicó el SHA-256 del paquete AutoUpdate.' }
    if($digest -notmatch '^(?i)sha256:(?<hash>[a-f0-9]{64})$'){ throw 'El SHA-256 publicado por GitHub no tiene un formato válido.' }

    $expected=$Matches['hash'].ToLowerInvariant()
    $actual=(Get-FileHash -LiteralPath $filePath -Algorithm SHA256 -ErrorAction Stop).Hash.ToLowerInvariant()
    if($actual -cne $expected){ throw 'La verificación SHA-256 falló. El paquete descargado no coincide con el publicado por GitHub.' }
    return $true
}

function Expand-BandaNVAutoUpdate([string]$zipPath,[string]$extractDir) {
    Add-Type -AssemblyName System.IO.Compression -ErrorAction SilentlyContinue
    Add-Type -AssemblyName System.IO.Compression.FileSystem -ErrorAction SilentlyContinue

    if(Test-Path -LiteralPath $extractDir){ Remove-Item -LiteralPath $extractDir -Recurse -Force -ErrorAction Stop }
    New-Item -ItemType Directory -Force -Path $extractDir | Out-Null

    # Estructura intencionalmente estricta en Phase 2:
    # AutoUpdate.zip debe contener BandaNV.exe en la raíz.
    $archive=$null
    try {
        try {
            $archive=[IO.Compression.ZipFile]::OpenRead($zipPath)
        } catch {
            throw 'El paquete AutoUpdate está dañado o no es un archivo ZIP válido.'
        }

        $files=@($archive.Entries | Where-Object { -not [string]::IsNullOrWhiteSpace($_.Name) })
        $names=@($files | ForEach-Object { $_.FullName.Replace('/','\') })

        if($names -notcontains 'BandaNV.exe') {
            throw 'El paquete AutoUpdate no contiene BandaNV.exe en la raíz.'
        }
        foreach($name in $names) {
            if($name -match '^(?i)(config|logs)\\') {
                throw 'El paquete AutoUpdate contiene datos que nunca deben reemplazarse (config o logs).'
            }
            if($name -match '(^|\\)\.\.(\\|$)' -or [IO.Path]::IsPathRooted($name)) {
                throw 'El paquete AutoUpdate contiene una ruta no segura.'
            }
        }
    } finally {
        if($null -ne $archive){ $archive.Dispose() }
    }

    [IO.Compression.ZipFile]::ExtractToDirectory($zipPath,$extractDir)
    $staged=Join-Path $extractDir 'BandaNV.exe'
    if(-not (Test-Path -LiteralPath $staged -PathType Leaf)) {
        throw 'No se pudo preparar BandaNV.exe desde AutoUpdate.zip.'
    }
    return $staged
}

function Start-BandaNVInstaller($result,$workspace) {
    $helper=Join-Path $script:AppDir 'NVupdate.exe'
    $app=Join-Path $script:AppDir 'BandaNV.exe'

    if(-not (Test-Path -LiteralPath $helper -PathType Leaf)) {
        throw 'No se encontró NVupdate.exe junto a BandaNV.exe.'
    }
    if(-not (Test-Path -LiteralPath $app -PathType Leaf)) {
        throw 'No se pudo localizar BandaNV.exe para actualizarlo.'
    }
    if($null -eq $workspace -or -not (Test-Path -LiteralPath $workspace.StagedExe -PathType Leaf)) {
        throw 'La actualización preparada ya no está disponible.'
    }

    function Quote-NVArg([string]$value) {
        if($null -eq $value){ return '""' }
        return '"' + $value.Replace('"','\"') + '"'
    }

    $args=@(
        '-ParentPid', [string]$PID,
        '-AppPath', (Quote-NVArg $app),
        '-StagedExe', (Quote-NVArg ([string]$workspace.StagedExe)),
        '-BackupPath', (Quote-NVArg ([string]$workspace.BackupPath)),
        '-ConfirmPath', (Quote-NVArg ([string]$workspace.ConfirmPath)),
        '-UpdateToken', (Quote-NVArg ([string]$workspace.Token)),
        '-ExpectedVersion', (Quote-NVArg ([string]$result.Available)),
        '-ReleaseTag', (Quote-NVArg ([string]$result.Tag))
    ) -join ' '

    Start-Process -FilePath $helper -ArgumentList $args -WorkingDirectory $script:AppDir | Out-Null

    # NVupdate queda esperando a que este proceso termine.
    [Windows.Forms.Application]::Exit()
}

function Show-BandaNVUpdateReadyDialog($result,$workspace,$owner=$null) {
    $form=New-Object Windows.Forms.Form
    $form.Text='BandaNV — Actualización lista'
    $form.Size=New-Object Drawing.Size(520,275)
    $form.StartPosition='CenterParent'
    $form.FormBorderStyle='FixedDialog'
    $form.MaximizeBox=$false
    $form.MinimizeBox=$false
    Initialize-ThemedForm $form

    $title=New-Object Windows.Forms.Label
    $title.Text='ACTUALIZACIÓN LISTA'
    $title.Font=New-Object Drawing.Font('Segoe UI',15,[Drawing.FontStyle]::Bold)
    $title.Location=New-Object Drawing.Point(24,22)
    $title.AutoSize=$true

    $info=New-Object Windows.Forms.Label
    $info.Text=([string]$result.Available+' fue descargada y verificada correctamente.'+[Environment]::NewLine+[Environment]::NewLine+'BandaNV debe reiniciarse para completar la actualización.')
    $info.Location=New-Object Drawing.Point(28,72)
    $info.Size=New-Object Drawing.Size(450,75)

    $later=New-Object Windows.Forms.Button
    $later.Text='MÁS TARDE'
    $later.Location=New-Object Drawing.Point(236,182)
    $later.Size=New-Object Drawing.Size(115,34)

    $restart=New-Object Windows.Forms.Button
    $restart.Text='REINICIAR Y ACTUALIZAR'
    $restart.Location=New-Object Drawing.Point(363,182)
    $restart.Size=New-Object Drawing.Size(115,34)

    $later.Add_Click({
        Remove-BandaNVUpdateWorkspace $workspace
        $form.Close()
    })

    $restart.Add_Click({
        try {
            $restart.Enabled=$false
            Start-BandaNVInstaller $result $workspace
            $form.Close()
        } catch {
            $restart.Enabled=$true
            [Windows.Forms.MessageBox]::Show(
                ('No se pudo iniciar NVupdate.'+[Environment]::NewLine+[Environment]::NewLine+$_.Exception.Message),
                'BandaNV — Actualización','OK','Error'
            ) | Out-Null
        }
    })

    $form.Add_FormClosing({
        if($form.DialogResult -eq [Windows.Forms.DialogResult]::None -and $restart.Enabled) {
            # Cerrar con X equivale a Más tarde: no dejamos temporales abandonados.
            Remove-BandaNVUpdateWorkspace $workspace
        }
    })

    $form.Controls.AddRange(@($title,$info,$later,$restart))
    Apply-DarkTheme $form
    $title.ForeColor=$script:ThemeAccent
    $info.ForeColor=$script:ThemeTextMuted
    Set-SecondaryButtonStyle $later
    Set-PrimaryButtonStyle $restart

    if($null -ne $owner -and -not $owner.IsDisposed){ [void]$form.ShowDialog($owner) }
    else { [void]$form.ShowDialog() }
}

function Show-BandaNVUpdateDownload($result,$owner=$null) {
    if([string]::IsNullOrWhiteSpace([string]$result.AssetUrl) -or [string]::IsNullOrWhiteSpace([string]$result.AssetName)) {
        [Windows.Forms.MessageBox]::Show(
            'La Release detectada no incluye el paquete oficial *_AutoUpdate.zip.'+[Environment]::NewLine+[Environment]::NewLine+
            'No se descargó ni modificó ningún archivo.',
            'BandaNV — Actualización','OK','Warning'
        ) | Out-Null
        return
    }
    if([string]::IsNullOrWhiteSpace([string]$result.Digest)) {
        [Windows.Forms.MessageBox]::Show(
            'GitHub no informó un SHA-256 para el paquete AutoUpdate. Por seguridad, BandaNV no lo instalará.',
            'BandaNV — Actualización','OK','Warning'
        ) | Out-Null
        return
    }

    $workspace=$null
    try { $workspace=New-BandaNVUpdateWorkspace }
    catch {
        [Windows.Forms.MessageBox]::Show(('No se pudo preparar la actualización.'+[Environment]::NewLine+[Environment]::NewLine+$_.Exception.Message),'BandaNV — Actualización','OK','Error')|Out-Null
        return
    }

    $form=New-Object Windows.Forms.Form
    $form.Text='BandaNV — Descargando actualización'
    $form.Size=New-Object Drawing.Size(520,270)
    $form.StartPosition='CenterParent'
    $form.FormBorderStyle='FixedDialog'
    $form.MaximizeBox=$false
    $form.MinimizeBox=$false
    Initialize-ThemedForm $form

    $title=New-Object Windows.Forms.Label
    $title.Text='DESCARGANDO ACTUALIZACIÓN'
    $title.Font=New-Object Drawing.Font('Segoe UI',15,[Drawing.FontStyle]::Bold)
    $title.Location=New-Object Drawing.Point(24,22)
    $title.AutoSize=$true

    $version=New-Object Windows.Forms.Label
    $version.Text=[string]$result.Available
    $version.Location=New-Object Drawing.Point(28,65)
    $version.AutoSize=$true

    $bar=New-Object Windows.Forms.ProgressBar
    $bar.Location=New-Object Drawing.Point(28,100)
    $bar.Size=New-Object Drawing.Size(450,24)
    $bar.Minimum=0
    $bar.Maximum=100
    $bar.Value=0

    $percent=New-Object Windows.Forms.Label
    $percent.Text='0 %'
    $percent.Location=New-Object Drawing.Point(28,132)
    $percent.Size=New-Object Drawing.Size(450,24)
    $percent.TextAlign='MiddleCenter'

    $state=New-Object Windows.Forms.Label
    $state.Text='Descargando desde GitHub...'
    $state.Location=New-Object Drawing.Point(28,158)
    $state.Size=New-Object Drawing.Size(450,24)
    $state.TextAlign='MiddleCenter'

    $cancel=New-Object Windows.Forms.Button
    $cancel.Text='CANCELAR'
    $cancel.Location=New-Object Drawing.Point(363,194)
    $cancel.Size=New-Object Drawing.Size(115,32)

    $context=[PSCustomObject]@{
        Finished=$false
        Success=$false
        CancelRequested=$false
        Error=''
        StagedExe=''
    }

    $wc=New-Object Net.WebClient
    $wc.Headers.Add('User-Agent','BandaNV-Updater/1.0')
    $wc.Headers.Add('Accept','application/octet-stream')

    $progressHandler=[Net.DownloadProgressChangedEventHandler]{
        param($sender,$e)
        if($context.Finished){ return }
        $p=[Math]::Max(0,[Math]::Min(100,[int]$e.ProgressPercentage))
        $bar.Value=$p
        $percent.Text=($p.ToString()+' %')
    }

    $completedHandler=[ComponentModel.AsyncCompletedEventHandler]{
        param($sender,$e)
        if($context.Finished){ return }

        try {
            if($e.Cancelled -or $context.CancelRequested) {
                $context.Error='Cancelado por el usuario.'
                return
            }
            if($null -ne $e.Error) {
                throw $e.Error
            }

            $bar.Value=100
            $percent.Text='100 %'
            $state.Text='Verificando integridad SHA-256...'
            [Windows.Forms.Application]::DoEvents()

            [void](Test-BandaNVUpdateDigest ([string]$workspace.ZipPath) ([string]$result.Digest))

            $state.Text='Preparando actualización...'
            [Windows.Forms.Application]::DoEvents()

            $context.StagedExe=Expand-BandaNVAutoUpdate ([string]$workspace.ZipPath) ([string]$workspace.ExtractDir)
            $workspace.StagedExe=$context.StagedExe
            $context.Success=$true
        } catch {
            $context.Error=$_.Exception.Message
        } finally {
            $context.Finished=$true
            try { $form.Close() } catch {}
        }
    }.GetNewClosure()

    $wc.add_DownloadProgressChanged($progressHandler)
    $wc.add_DownloadFileCompleted($completedHandler)

    $cancel.Add_Click({
        if(-not $context.Finished) {
            $context.CancelRequested=$true
            $cancel.Enabled=$false
            $state.Text='Cancelando...'
            try { $wc.CancelAsync() } catch {}
        }
    })

    $form.Add_FormClosing({
        param($sender,$e)
        if(-not $context.Finished) {
            $e.Cancel=$true
            if(-not $context.CancelRequested) {
                $context.CancelRequested=$true
                $cancel.Enabled=$false
                $state.Text='Cancelando...'
                try { $wc.CancelAsync() } catch {}
            }
        }
    })

    $form.Controls.AddRange(@($title,$version,$bar,$percent,$state,$cancel))
    Apply-DarkTheme $form
    $title.ForeColor=$script:ThemeAccent
    $version.ForeColor=$script:ThemeText
    $percent.ForeColor=$script:ThemeAccent
    $state.ForeColor=$script:ThemeTextMuted
    Set-SecondaryButtonStyle $cancel

    try {
        $wc.DownloadFileAsync([Uri][string]$result.AssetUrl,[string]$workspace.ZipPath)
        if($null -ne $owner -and -not $owner.IsDisposed){ [void]$form.ShowDialog($owner) }
        else { [void]$form.ShowDialog() }
    } catch {
        $context.Error=$_.Exception.Message
        $context.Finished=$true
    } finally {
        try { $wc.remove_DownloadProgressChanged($progressHandler) } catch {}
        try { $wc.remove_DownloadFileCompleted($completedHandler) } catch {}
        try { $wc.Dispose() } catch {}
        try { $form.Dispose() } catch {}
    }

    if($context.Success) {
        Show-BandaNVUpdateReadyDialog $result $workspace $owner
    } else {
        Remove-BandaNVUpdateWorkspace $workspace
        if(-not $context.CancelRequested -and -not [string]::IsNullOrWhiteSpace([string]$context.Error)) {
            [Windows.Forms.MessageBox]::Show(
                ('No se pudo preparar la actualización.'+[Environment]::NewLine+[Environment]::NewLine+[string]$context.Error+[Environment]::NewLine+[Environment]::NewLine+'Tu instalación actual no fue modificada.'),
                'BandaNV — Actualización','OK','Error'
            ) | Out-Null
        }
    }
}

function Show-BandaNVUpdateDialog($result,$owner=$null) {
