$organize.Add_Click({Show-OrganizationPreview $status $last $organize $main})
$history.Add_Click({Show-History; Refresh-Main})
$finder.Add_Click({Show-FileSearch $main; Refresh-Main})
$config.Add_Click({Show-Config; Refresh-Main})

$main.Controls.AddRange(@($brand,$ver,$verAuthor,$accentLine,$folderLabel,$folder,$organize,$status,$lastTitle,$last,$history,$finder,$config))
Apply-DarkTheme $main
# El branding comparte la zona superior con la firma y el separador.
# Dejar el logo al fondo y traer firma/separador al frente evita solapamientos.
$brand.SendToBack()
$ver.BringToFront()
$verAuthor.BringToFront()
$accentLine.BringToFront()
$accentLine.BackColor=$script:ThemeAccent
$ver.ForeColor=$script:ThemeTextMuted
$verAuthor.ForeColor=$script:ThemeText
$folderLabel.ForeColor=$script:ThemeAccent
$folder.ForeColor=$script:ThemeTextMuted
$status.ForeColor=$script:ThemeAccent
$lastTitle.ForeColor=$script:ThemeTextMuted
$last.ForeColor=$script:ThemeText
Set-PrimaryButtonStyle $organize
Set-SecondaryButtonStyle $history
Set-SecondaryButtonStyle $finder
Set-SecondaryButtonStyle $config

$main.Add_Shown({
    Refresh-Main

    # La UI ya está completamente tematizada en este punto.
    # Mostramos la ventana inmediatamente y recién después programamos
    # el chequeo de actualizaciones.
    $main.Opacity=1
    $main.Refresh()

    # Handshake con NVupdate.exe: recién confirmamos cuando la nueva
    # BandaNV llegó realmente a mostrar su ventana principal.
    Confirm-PendingUpdate
    Clear-BandaNVFailedUpdateStateIfObsolete

    try {
        $startupCfg=Load-Config
        if([bool]$startupCfg.checkUpdatesOnStartup){ Start-BandaNVStartupUpdateCheck $main }
    } catch {}
})
[void]$main.ShowDialog()
